    24	    public Reservation createReservation(String roomNumber, String guestName, String guestEmail,
    25	                                        String guestCpf, LocalDate checkIn, LocalDate checkOut,
    26	                                        int guests, RatePlan ratePlan, String companyCode) {
    27	        validateReservationRequest(roomNumber, checkIn, checkOut, guests, ratePlan, companyCode);
    28	
    29	        Room room = roomRepository.findByNumber(roomNumber)
    30	                .orElseThrow(() -> new RoomNotFoundException("Room not found"));
    31	
    32	        if (guests > room.getCapacity()) {
    33	            throw new CapacityExceededException("Number of guests exceeds room capacity");
    34	        }
    35	
    36	        if (reservationRepository.hasConflict(roomNumber, checkIn, checkOut, null)) {
    37	            throw new RoomUnavailableException("Room is not available for the selected dates");
    38	        }
    39	
    40	        int nights = (int) checkIn.until(checkOut).getDays();
    41	        PricingService.PriceBreakdown price = pricingService.calculatePrice(room, checkIn, checkOut, ratePlan, companyCode);
    42	
    43	        Long id = reservationRepository.nextId();
    44	        Reservation reservation = new Reservation(
    45	                id, roomNumber, guestName, guestEmail, guestCpf,
    46	                checkIn, checkOut, guests, ratePlan, companyCode,
    47	                nights, price.subtotal, price.discount, price.total
    48	        );
    49	
    50	        return reservationRepository.save(reservation);
    51	    }
    52	
    53	    public Reservation confirmReservation(Long id) {
    54	        Reservation reservation = findReservation(id);
    55	
    56	        if (reservation.getStatus() != ReservationStatus.PENDING) {
    57	            throw new OperationNotAllowedException("Can only confirm pending reservations");
    58	        }
    59	
    60	        reservation.setStatus(ReservationStatus.CONFIRMED);
    61	        reservation.setAmountPaid(reservation.getTotal());
    62	        reservationRepository.save(reservation);
    63	
    64	        emailService.sendConfirmationEmail(reservation);
    65	
    66	        return reservation;
    67	    }
    68	
    69	    public Reservation cancelReservation(Long id) {
    70	        Reservation reservation = findReservation(id);
    71	
    72	        if (reservation.getStatus() != ReservationStatus.PENDING &&
    73	            reservation.getStatus() != ReservationStatus.CONFIRMED) {
    74	            throw new OperationNotAllowedException("Can only cancel pending or confirmed reservations");
    75	        }
    76	
    77	        BigDecimal refundAmount = pricingService.calculateRefund(
    78	                reservation.getAmountPaid(), reservation.getRatePlan());
    79	
    80	        reservation.setStatus(ReservationStatus.CANCELLED);
    81	        reservation.setRefund(refundAmount);
    82	        reservationRepository.save(reservation);
    83	
    84	        return reservation;
    85	    }
    86	
    87	    public Reservation checkIn(Long id) {
    88	        Reservation reservation = findReservation(id);
    89	
    90	        if (reservation.getStatus() != ReservationStatus.CONFIRMED) {
    91	            throw new OperationNotAllowedException("Can only check in confirmed reservations");
    92	        }
    93	
    94	        reservation.setStatus(ReservationStatus.CHECKED_IN);
    95	        reservationRepository.save(reservation);
    96	
    97	        return reservation;
    98	    }
    99	
   100	    public Reservation checkOut(Long id) {
   101	        Reservation reservation = findReservation(id);
   102	
   103	        if (reservation.getStatus() != ReservationStatus.CHECKED_IN) {
   104	            throw new OperationNotAllowedException("Can only check out guests who have checked in");
   105	        }
   106	
   107	        reservation.setStatus(ReservationStatus.CHECKED_OUT);
   108	        reservationRepository.save(reservation);
   109	
   110	        return reservation;
   111	    }
   112	
   113	    public Reservation findReservation(Long id) {
   114	        return reservationRepository.findById(id)
   115	                .orElseThrow(() -> new ReservationNotFoundException("Reservation not found"));
   116	    }
   117	
   118	    private void validateReservationRequest(String roomNumber, LocalDate checkIn, LocalDate checkOut,
   119	                                          int guests, RatePlan ratePlan, String companyCode) {
   120	        if (checkIn == null || checkOut == null) {
   121	            throw new InvalidRequestException("Check-in and check-out dates are required");
   122	        }
   123	
   124	        if (!checkOut.isAfter(checkIn)) {
   125	            throw new InvalidRequestException("Check-out must be after check-in");
   126	        }
   127	
   128	        if (guests < 1) {
   129	            throw new InvalidRequestException("At least one guest is required");
   130	        }
   131	
   132	        Room room = roomRepository.findByNumber(roomNumber)
   133	                .orElseThrow(() -> new RoomNotFoundException("Room not found"));
   134	
   135	        try {
   136	            pricingService.validateRatePlan(ratePlan, checkIn, checkOut, companyCode);
   137	        } catch (IllegalArgumentException e) {
   138	            throw new InvalidRequestException(e.getMessage());
   139	        }
   140	    }
   141	
