    45	    private BigDecimal calculateSubtotal(Room room, LocalDate checkIn, LocalDate checkOut) {
    46	        BigDecimal total = BigDecimal.ZERO;
    47	        LocalDate current = checkIn;
    48	
    49	        while (current.isBefore(checkOut)) {
    50	            BigDecimal nightRate = room.getNightlyRate();
    51	            if (isHighSeason(current)) {
    52	                nightRate = round(nightRate.multiply(HIGH_SEASON_MULTIPLIER));
    53	            }
    54	            total = total.add(nightRate);
    55	            current = current.plusDays(1);
    56	        }
    57	
    58	        return round(total);
    59	    }
    60	
    61	    private BigDecimal calculateDiscount(BigDecimal subtotal, RatePlan ratePlan, String companyCode) {
    62	        BigDecimal discountRate = switch (ratePlan) {
    63	            case NON_REFUNDABLE -> NON_REFUNDABLE_DISCOUNT;
    64	            case CORPORATE -> {
    65	                Company company = Company.fromCode(companyCode);
    66	                yield company != null ? company.getDiscountRate() : BigDecimal.ZERO;
    67	            }
    68	            case LONG_STAY -> LONG_STAY_DISCOUNT;
    69	            default -> BigDecimal.ZERO;
    70	        };
    71	
    72	        return round(subtotal.multiply(discountRate));
    73	    }
    74	
    75	    private BigDecimal getWeekendPackagePrice(RoomType roomType) {
    76	        return switch (roomType) {
    77	            case STANDARD -> new BigDecimal("520.00");
    78	            case DELUXE -> new BigDecimal("820.00");
    79	            case SUITE -> new BigDecimal("1200.00");
    80	        };
    81	    }
    82	
    83	    private boolean isHighSeason(LocalDate date) {
    84	        Month month = date.getMonth();
    85	        int day = date.getDayOfMonth();
    86	
    87	        // Julho inteiro
    88	        if (month == Month.JULY) {
    89	            return true;
    90	        }
    91	
    92	        // Janeiro e fevereiro inteiros
    93	        if (month == Month.JANUARY || month == Month.FEBRUARY) {
    94	            return true;
    95	        }
    96	
    97	        // 15 de dezembro em diante
    98	        if (month == Month.DECEMBER && day >= 15) {
    99	            return true;
   100	        }
   101	
   102	        return false;
   103	    }
   104	
   105	    public BigDecimal calculateRefund(BigDecimal amountPaid, RatePlan ratePlan) {
   106	        BigDecimal refundAmount = switch (ratePlan) {
   107	            case STANDARD, CORPORATE, LONG_STAY -> amountPaid;
   108	            case WEEKEND_PACKAGE -> round(amountPaid.multiply(new BigDecimal("0.50")));
   109	            case NON_REFUNDABLE -> BigDecimal.ZERO;
   110	        };
   111	
   112	        return round(refundAmount);
   113	    }
   114	
   115	    public void validateRatePlan(RatePlan ratePlan, LocalDate checkIn, LocalDate checkOut, String companyCode) {
   116	        int nights = (int) checkIn.until(checkOut).getDays();
   117	
   118	        switch (ratePlan) {
   119	            case CORPORATE -> {
   120	                if (Company.fromCode(companyCode) == null) {
   121	                    throw new IllegalArgumentException("Invalid company code for corporate rate plan");
   122	                }
   123	            }
   124	            case WEEKEND_PACKAGE -> {
   125	                if (nights != 2) {
   126	                    throw new IllegalArgumentException("Weekend package requires exactly 2 nights");
   127	                }
   128	                if (checkIn.getDayOfWeek() != DayOfWeek.FRIDAY) {
   129	                    throw new IllegalArgumentException("Weekend package must start on Friday");
   130	                }
   131	            }
   132	            case LONG_STAY -> {
   133	                if (nights < LONG_STAY_MIN_NIGHTS) {
   134	                    throw new IllegalArgumentException("Long stay requires at least 7 nights");
   135	                }
   136	            }
   137	        }
   138	    }
   139	
   140	    private BigDecimal round(BigDecimal value) {
   141	        return value.setScale(2, RoundingMode.HALF_EVEN);
   142	    }
   143	}
