 19	public class ApiController {
 20	    private final RoomRepository roomRepository;
 21	    private final ReservationService reservationService;
 22	    private final DocumentService documentService;
 23	    private final MessageRepository messageRepository;
 24	    private final ReportService reportService;
 25	
 26	    public ApiController(RoomRepository roomRepository, ReservationService reservationService,
 27	                        DocumentService documentService, MessageRepository messageRepository,
 28	                        ReportService reportService) {
 29	        this.roomRepository = roomRepository;
 30	        this.reservationService = reservationService;
 31	        this.documentService = documentService;
 32	        this.messageRepository = messageRepository;
 33	        this.reportService = reportService;
 34	    }
 35	
 36	    public void registerRoutes(Javalin app) {
 37	        app.get("/rooms", this::getRooms);
 38	        app.post("/reservations", this::createReservation);
 39	        app.get("/reservations/{id}", this::getReservation);
 40	        app.post("/reservations/{id}/confirmation", this::confirmReservation);
 41	        app.post("/reservations/{id}/cancellation", this::cancelReservation);
 42	        app.post("/reservations/{id}/check-in", this::checkIn);
 43	        app.post("/reservations/{id}/check-out", this::checkOut);
 44	        app.get("/reservations/{id}/document", this::getDocument);
 45	        app.get("/messages", this::getMessages);
 46	        app.get("/reports/occupancy", this::getOccupancyReport);
 47	        app.get("/reports/revenue", this::getRevenueReport);
 48	
 49	        app.exception(ReservationService.InvalidRequestException.class, (e, ctx) -> {
 50	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", e.getMessage()));
 51	        });
 52	
 53	        app.exception(ReservationService.RoomNotFoundException.class, (e, ctx) -> {
 54	            ctx.status(404).json(new ErrorResponse("ROOM_NOT_FOUND", e.getMessage()));
 55	        });
 56	
 57	        app.exception(ReservationService.ReservationNotFoundException.class, (e, ctx) -> {
