 93	    private void createReservation(Context ctx) {
 94	        CreateReservationRequest request = ctx.bodyAsClass(CreateReservationRequest.class);
 95	
 96	        validateRequired(request.roomNumber(), "roomNumber");
 97	        validateRequired(request.guestName(), "guestName");
 98	        validateRequired(request.guestEmail(), "guestEmail");
 99	        validateRequired(request.guestCpf(), "guestCpf");
100	        validateRequired(request.checkIn(), "checkIn");
101	        validateRequired(request.checkOut(), "checkOut");
102	        validateRequired(request.guests(), "guests");
103	        validateRequired(request.ratePlan(), "ratePlan");
104	
105	        LocalDate checkIn = parseDate(request.checkIn());
106	        LocalDate checkOut = parseDate(request.checkOut());
107	        RatePlan ratePlan = parseRatePlan(request.ratePlan());
108	
109	        Reservation reservation = reservationService.createReservation(
110	                request.roomNumber(),
111	                request.guestName(),
112	                request.guestEmail(),
113	                request.guestCpf(),
114	                checkIn,
115	                checkOut,
116	                request.guests(),
117	                ratePlan,
118	                request.companyCode()
119	        );
