217	    private LocalDate parseDate(String dateStr) {
218	        try {
219	            return LocalDate.parse(dateStr);
220	        } catch (DateTimeParseException e) {
221	            throw new ReservationService.InvalidRequestException("Invalid date format");
222	        }
