     7	import java.math.BigDecimal;
     8	import java.text.NumberFormat;
     9	import java.time.format.DateTimeFormatter;
    10	import java.util.Locale;
    11	
    12	public class DocumentService {
    13	    private static final DateTimeFormatter DATE_FORMATTER = DateTimeFormatter.ofPattern("dd/MM/yyyy");
    14	    private static final NumberFormat CURRENCY_FORMAT = NumberFormat.getCurrencyInstance(new Locale("pt", "BR"));
    15	    private final RoomRepository roomRepository;
    16	
    17	    public DocumentService(RoomRepository roomRepository) {
    18	        this.roomRepository = roomRepository;
    19	    }
    20	
    21	    public String generateReceipt(Reservation reservation) {
    22	        if (reservation.getStatus() == ReservationStatus.PENDING ||
    23	            reservation.getStatus() == ReservationStatus.CANCELLED) {
    24	            throw new IllegalStateException("Receipt can only be generated for paid reservations");
    25	        }
    26	
    27	        String roomType = roomRepository.findByNumber(reservation.getRoomNumber())
    28	                .map(r -> r.getType().name())
    29	                .orElse("");
    30	
    31	        StringBuilder receipt = new StringBuilder();
    32	        receipt.append(String.format("Comprovante de reserva nº %d%n", reservation.getId()));
    33	        receipt.append(String.format("Hóspede: %s (CPF %s)%n",
    34	                reservation.getGuestName(), formatCpf(reservation.getGuestCpf())));
    35	        receipt.append(String.format("Quarto: %s (%s)%n", reservation.getRoomNumber(), roomType));
    36	        receipt.append(String.format("Entrada: %s | Saída: %s | %s%n",
    37	                reservation.getCheckIn().format(DATE_FORMATTER),
    38	                reservation.getCheckOut().format(DATE_FORMATTER),
    39	                formatNights(reservation.getNights())));
    40	        receipt.append(String.format("Diárias: %s%n", formatCurrency(reservation.getSubtotal())));
    41	
    42	        if (reservation.getDiscount().compareTo(BigDecimal.ZERO) > 0) {
    43	            receipt.append(String.format("Desconto: %s%n", formatCurrency(reservation.getDiscount())));
    44	        }
    45	
    46	        receipt.append(String.format("Total: %s", formatCurrency(reservation.getTotal())));
    47	
    48	        return receipt.toString();
    49	    }
    50	
    51	    private String formatCpf(String cpf) {
    52	        if (cpf == null || cpf.length() != 11) {
    53	            return cpf;
    54	        }
    55	        return String.format("%s.%s.%s-%s",
    56	                cpf.substring(0, 3),
    57	                cpf.substring(3, 6),
    58	                cpf.substring(6, 9),
    59	                cpf.substring(9, 11));
    60	    }
    61	
    62	    private String formatNights(int nights) {
    63	        return nights == 1 ? "1 diária" : nights + " diárias";
    64	    }
    65	
    66	    private String formatCurrency(BigDecimal value) {
    67	        return CURRENCY_FORMAT.format(value);
    68	    }
    69	}
