   101	package com.pousadamarealta.service;
   102	
   103	import com.pousadamarealta.model.Reservation;
   104	import com.pousadamarealta.model.ReservationStatus;
   105	import com.pousadamarealta.repository.ReservationRepository;
   106	import com.pousadamarealta.repository.RoomRepository;
   107	
   108	import java.math.BigDecimal;
   109	import java.time.LocalDate;
   110	import java.time.YearMonth;
   111	import java.time.format.DateTimeFormatter;
   112	import java.util.Comparator;
   113	import java.util.List;
   114	import java.util.stream.Collectors;
   115	
   116	public class ReportService {
   117	    private static final DateTimeFormatter DATE_FORMATTER = DateTimeFormatter.ofPattern("yyyy-MM-dd");
   118	    private final ReservationRepository reservationRepository;
   119	    private final RoomRepository roomRepository;
   120	
   121	    public ReportService(ReservationRepository reservationRepository, RoomRepository roomRepository) {
   122	        this.reservationRepository = reservationRepository;
   123	        this.roomRepository = roomRepository;
   124	    }
   125	
   126	    public String generateOccupancyReport(LocalDate date) {
   127	        List<Reservation> occupiedReservations = reservationRepository.findAll().stream()
   128	                .filter(r -> r.getStatus() != ReservationStatus.PENDING)
   129	                .filter(r -> r.getStatus() != ReservationStatus.CANCELLED)
   130	                .filter(r -> isOccupiedOnDate(r, date))
   131	                .sorted(Comparator.comparing(Reservation::getRoomNumber))
   132	                .toList();
   133	
   134	        StringBuilder csv = new StringBuilder();
   135	        csv.append("room,type,reservation,check_in,check_out\n");
   136	
   137	        for (Reservation reservation : occupiedReservations) {
   138	            String roomType = roomRepository.findByNumber(reservation.getRoomNumber())
   139	                    .map(r -> r.getType().name())
   140	                    .orElse("");
   141	
   142	            csv.append(String.format("%s,%s,%d,%s,%s\n",
   143	                    reservation.getRoomNumber(),
   144	                    roomType,
   145	                    reservation.getId(),
   146	                    reservation.getCheckIn().format(DATE_FORMATTER),
   147	                    reservation.getCheckOut().format(DATE_FORMATTER)));
   148	        }
   149	
   150	        int totalRooms = roomRepository.findAll().size();
   151	        csv.append(String.format("total,%d/%d", occupiedReservations.size(), totalRooms));
   152	
   153	        return csv.toString();
   154	    }
   155	
   156	    public String generateRevenueReport(YearMonth month) {
   157	        List<Reservation> monthReservations = reservationRepository.findAll().stream()
   158	                .filter(r -> YearMonth.from(r.getCheckIn()).equals(month))
   159	                .filter(r -> hasRevenue(r))
   160	                .sorted(Comparator.comparing(Reservation::getCheckIn)
   161	                        .thenComparing(Reservation::getId))
   162	                .toList();
   163	
   164	        StringBuilder csv = new StringBuilder();
   165	        csv.append("reservation,room,check_in,check_out,status,amount\n");
   166	
   167	        BigDecimal total = BigDecimal.ZERO;
   168	
   169	        for (Reservation reservation : monthReservations) {
   170	            BigDecimal revenue = calculateRevenue(reservation);
   171	            total = total.add(revenue);
   172	
   173	            csv.append(String.format("%d,%s,%s,%s,%s,%s\n",
   174	                    reservation.getId(),
   175	                    reservation.getRoomNumber(),
   176	                    reservation.getCheckIn().format(DATE_FORMATTER),
   177	                    reservation.getCheckOut().format(DATE_FORMATTER),
   178	                    reservation.getStatus().name(),
   179	                    formatAmount(revenue)));
   180	        }
   181	
   182	        csv.append(String.format("total,%s", formatAmount(total)));
   183	
   184	        return csv.toString();
   185	    }
   186	
   187	    private boolean isOccupiedOnDate(Reservation reservation, LocalDate date) {
   188	        return !date.isBefore(reservation.getCheckIn()) && date.isBefore(reservation.getCheckOut());
   189	    }
